// tb_top.v -- top-level testbench: UART BFM driven by a host-generated byte script + SRAM model.
// Script lines: "S hh" send byte, "R n" wait until n bytes received in total, "X 0" end.
`timescale 1ns/1ps
`ifndef N_HID
 `define N_HID 16
`endif
`ifndef SH
 `define SH 4
`endif
`ifndef BAUD_DIV
 `define BAUD_DIV 8
`endif
module tb_top;
    reg CLOCK_50 = 0; always #10 CLOCK_50 = ~CLOCK_50;
    reg [3:0] KEY = 4'b1110;
    reg rxd = 1'b1; wire txd;
    wire [19:0] A; wire [15:0] DQ; wire CE_N, OE_N, WE_N, UB_N, LB_N;
    wire [8:0] LEDG; wire [17:0] LEDR; wire [6:0] H0, H1, H2, H3;
    de2_115_sena_top #(.N_HID(`N_HID), .SH(`SH), .BAUD_DIV(`BAUD_DIV)) dut (
        .CLOCK_50(CLOCK_50), .KEY(KEY), .UART_RXD(rxd), .UART_TXD(txd),
        .SRAM_ADDR(A), .SRAM_DQ(DQ), .SRAM_CE_N(CE_N), .SRAM_OE_N(OE_N), .SRAM_WE_N(WE_N), .SRAM_UB_N(UB_N), .SRAM_LB_N(LB_N),
        .LEDG(LEDG), .LEDR(LEDR), .HEX0(H0), .HEX1(H1), .HEX2(H2), .HEX3(H3));
    is61wv102416_model sram (.A(A), .DQ(DQ), .CE_N(CE_N), .OE_N(OE_N), .WE_N(WE_N), .UB_N(UB_N), .LB_N(LB_N));

    localparam real BIT = `BAUD_DIV * 40.0;
    integer nrx = 0, flog, fs, code, val, nsent = 0, nferr = 0;
    reg [8*8:1] tok;
    // ---- receiver (board TX -> host)
    reg [7:0] rb; integer k;
    always @(negedge txd) begin : rxmon
        #(BIT * 1.5);
        for (k = 0; k < 8; k = k + 1) begin rb[k] = txd; #(BIT); end
        if (txd !== 1'b1) nferr = nferr + 1;
        $fwrite(flog, "%02x\n", rb); nrx = nrx + 1;
    end
    task send(input [7:0] b);
        integer j;
        begin
            rxd = 0; #(BIT);
            for (j = 0; j < 8; j = j + 1) begin rxd = b[j]; #(BIT); end
            rxd = 1; #(BIT); nsent = nsent + 1;
        end
    endtask
    initial begin
        flog = $fopen(`RXLOG, "w");
        fs = $fopen(`SCRIPT, "r");
        if (fs == 0) begin $display("cannot open script"); $finish; end
        #200 KEY = 4'b1111; #2000;
        while (!$feof(fs)) begin
            code = $fscanf(fs, "%s", tok);
            if (code != 1) begin end
            else if (tok == "S") begin code = $fscanf(fs, "%h", val); send(val[7:0]); end
            else if (tok == "R") begin code = $fscanf(fs, "%d", val); wait (nrx >= val); end
            else if (tok == "X") begin code = $fscanf(fs, "%d", val);
                #(BIT * 20);
                $display("TB_DONE sent=%0d received=%0d frame_err_rx_side=%0d sram_err=%0d LEDR=%h t=%0t ns",
                         nsent, nrx, nferr, sram.n_err, LEDR, $time);
                $fclose(flog); $finish;
            end
        end
        $display("TB_EOF without X"); $fclose(flog); $finish;
    end
    // core-cycle progress
    initial begin : prog
        forever begin #(100_000_000); $display("t=%0d ms sent=%0d rx=%0d samples=%0d", $time / 1_000_000, nsent, nrx, dut.samples); end
    end
endmodule
